CREATE TABLE `booking` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) DEFAULT NULL,
  `eventId` varchar(191) NOT NULL,
  `status` enum('PENDING','CONFIRMED','CANCELLED','COMPLETED','WAITLIST') NOT NULL DEFAULT 'PENDING',
  `totalPrice` double NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `customerDetails` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`customerDetails`)),
  `paymentMethod` varchar(191) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `rating` int(11) DEFAULT NULL,
  `ratingComment` text DEFAULT NULL,
  `adminComment` text DEFAULT NULL,
  `certificated` tinyint(1) NOT NULL DEFAULT 0,
  `checkedIn` tinyint(1) NOT NULL DEFAULT 0,
  `paid` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `Booking_eventId_fkey` (`eventId`),
  KEY `Booking_userId_fkey` (`userId`),
  CONSTRAINT `Booking_eventId_fkey` FOREIGN KEY (`eventId`) REFERENCES `event` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `Booking_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
